const AIRPORTS_BY_CODE = new Map(AIRPORTS.map((airport) => [airport.code, airport])); const AIRPORTS_BY_ALIAS = new Map( AIRPORTS.flatMap((airport) => (airport.aliases ?? []).map((alias) => [alias, airport.code] as const)), );
export const ALL_AIRPORT_OPTIONS = AIRPORTS.map((airport) => airport.code); export const ORIGIN_AIRPORT_OPTIONS = ALL_AIRPORT_OPTIONS; export const DESTINATION_AIRPORT_OPTIONS = ALL_AIRPORT_OPTIONS; export const LANDING_DISCOVERY_AIRPORT_OPTIONS = ['BVA', 'LIS', 'BCN', 'CIA', 'OPO', 'AGP', 'PRG', 'BUD'];
const normalizeFreeText = (value: string): string => value.trim().toUpperCase().replace(/[^A-Z]/g, '');
export const normalizeAirportCode = (value: string): string => { const trimmed = value.trim().toUpperCase(); const bracketMatch = trimmed.match(/\(([A-Z]{3})\)$/); if (bracketMatch) { return normalizeAirportCode(bracketMatch[1]); }
const token = normalizeFreeText(value); if (AIRPORTS_BY_CODE.has(token)) { return token; }
const aliasTarget = AIRPORTS_BY_ALIAS.get(token); if (aliasTarget) { return aliasTarget; }
return token.slice(0, 4); };
export const getAirportMetadata = (value: string): AirportMetadata | null => { const code = normalizeAirportCode(value); return AIRPORTS_BY_CODE.get(code) ?? null; };
export const getAirportDisplay = (value: string): AirportDisplay => { const metadata = getAirportMetadata(value); const searchCode = normalizeAirportCode(value);
if (metadata) { return { ...metadata, searchCode }; }
return { code: searchCode || value.trim().toUpperCase(), city: searchCode || value.trim().toUpperCase(), country: 'Unknown destination', flag: '️', airportName: `${searchCode || value.trim().toUpperCase()} airport`, thumbnailUrl: 'https://images.unsplash.com/photo-1436491865332-7a61a109cc05?auto=format&fit=crop&w=1200&q=80', searchCode, }; };
export const buildAirportSearchText = (airport: Pick<AirportMetadata, 'code' | 'city' | 'country' | 'airportName' | 'aliases'>): string => ( [airport.code, airport.city, airport.country, airport.airportName, ...(airport.aliases ?? [])] .join(' ') .toLowerCase() );
export const formatAirportOptionLabel = (code: string): string => { const metadata = getAirportDisplay(code); return `${metadata.flag} ${metadata.city}, ${metadata.country} (${metadata.code})`; };
export const groupAirportsByCountry = (codes: string[]): AirportGroup[] => { const groups = new Map<string, AirportMetadata[]>();
codes.forEach((code) => { const metadata = getAirportMetadata(code); if (!metadata) { return; }
const current = groups.get(metadata.country) ?? []; current.push(metadata); groups.set(metadata.country, current); });
return Array.from(groups.entries()) .map(([country, airports]) => ({ country, flag: airports[0]?.flag ?? '️', airports: airports.sort((left, right) => left.city.localeCompare(right.city)), })) .sort((left, right) => left.country.localeCompare(right.country)); };

export interface AirportMetadata { code: string; city: string; country: string; flag: string; airportName: string; thumbnailUrl: string; fareHighlight?: string; aliases?: string[]; }
export interface AirportGroup { country: string; flag: string; airports: AirportMetadata[]; }
export interface AirportDisplay extends AirportMetadata { searchCode: string; }
